package com.hau.notification.presentation.advice;import com.hau.notification.domain.exception.*;import com.hau.notification.presentation.response.ApiErrorResponse;import jakarta.servlet.http.HttpServletRequest;import org.slf4j.*;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class GlobalExceptionHandler{private static final Logger log=LoggerFactory.getLogger(GlobalExceptionHandler.class);@ExceptionHandler(DomainException.class)ResponseEntity<ApiErrorResponse>domain(DomainException e,HttpServletRequest r){HttpStatus s=e instanceof NotificationNotFoundException?HttpStatus.NOT_FOUND:e instanceof ForbiddenNotificationAccessException?HttpStatus.FORBIDDEN:HttpStatus.BAD_REQUEST;return response(s,e.getCode(),e.getMessage(),r);}@ExceptionHandler({MethodArgumentNotValidException.class,IllegalArgumentException.class})ResponseEntity<ApiErrorResponse>bad(Exception e,HttpServletRequest r){return response(HttpStatus.BAD_REQUEST,"VALIDATION_ERROR","Invalid request",r);}@ExceptionHandler(Exception.class)ResponseEntity<ApiErrorResponse>unexpected(Exception e,HttpServletRequest r){log.error("Unexpected notification service error",e);return response(HttpStatus.INTERNAL_SERVER_ERROR,"INTERNAL_ERROR","An unexpected error occurred",r);}private ResponseEntity<ApiErrorResponse>response(HttpStatus s,String c,String m,HttpServletRequest r){return ResponseEntity.status(s).body(ApiErrorResponse.of(c,m,r.getRequestURI(),r.getHeader("X-Correlation-Id")));}}
